class L{String s(boolean P,String I){var l=I.lines().toList();int W=l.get(0).length()+2,N=W*(l.size()+2);char[]g=new char[N];for(int r=0;r<l.size();r++)l.get(r).getChars(0,W-2,g,(r+1)*W+1);boolean[]s=new boolean[N];int[]D={1,-1,W,-W},q=new int[N];long A=0;for(int S=0;S<N;S++){if(s[S]|g[S]<1)continue;int h=0,t=1,n=0,e=0,c=0;char o=g[S];q[0]=S;s[S]=true;while(h<t){int p=q[h++];n++;for(int d:D){int j=p+d;if(g[j]!=o)e++;else if(!s[j]){s[j]=true;q[t++]=j;}}for(int a=-W;a<=W;a+=2*W)for(int b=-1;b<2;b+=2){boolean x=g[p+a]==o,y=g[p+b]==o;if(!x&!y|x&y&g[p+a+b]!=o)c++;}}A+=(long)n*(P?e:c);}return A+"";}}
